    #   comparison.
    # @param score [Integer, nil] Currently not used by the server API.
    # @param key_mode [String, nil] Makes the publish conditional: "if_new" writes only if the
    #   key does not exist, "if_exists" only if it exists. Empty always
    #   writes.
    # @param timeout [Numeric, nil] Seconds bounding the call: request_timeout when nil.
    # @return [MapPublishResult]
    # @raise [Error]
    def map_publish(
      channel:,
      key:,
      data: nil,
      b64data: nil,
      stream_data: nil,
      b64stream_data: nil,
      tags: nil,
      idempotency_key: nil,
      delta: nil,
      version: nil,
      version_epoch: nil,
      score: nil,
      key_mode: nil,
      timeout: nil
    )
      invoke("map_publish", MapPublishResult, timeout) do
        Requests.map_publish(
          channel,
          key,
          data,
          b64data,
          stream_data,
          b64stream_data,
          tags,
          idempotency_key,
          delta,
          version,
          version_epoch,
          score,
          key_mode
        )
      end
    end

