  # The commands of Batch, one per method of api.proto.
  #
  # @api private
  module BatchMethods
    # Publishes data into a channel.
    #
    # Adds the command to the batch: its Pending holds the result once the batch
    # is sent.
    #
    # @param channel [String, nil] The name of the channel to publish into. Required.
    # @param data [Object, nil] The payload to publish. Required unless b64data is set. In the
    #   HTTP API it is any JSON value; over GRPC it may be binary.
    # @param b64data [String, nil] A base64-encoded binary payload, an alternative to `data` to
    #   send binary over the HTTP API. Centrifugo decodes it before publishing.
    # @param skip_history [Boolean, nil] Skips adding this publication to the channel history.
    # @param tags [Hash{String => String}] A map of arbitrary string keys and values attached to the
    #   publication and delivered to clients.
    # @param idempotency_key [String, nil] Drops duplicate publications upon retries: a
    #   publication with a key already used in the channel is not published
    #   again, and the first one's result is returned. It acts per channel;
    #   results are kept for 5 minutes by default. The memory, Redis and
    #   PostgreSQL brokers keep keys; the NATS broker ignores them.
    # @param delta [Boolean, nil] Tells Centrifugo to construct a delta update, if possible, when
    #   broadcasting the publication to subscribers.
    # @param version [Integer, nil] When > 0, the version of the document being sent:
    #   publications with a version less than or equal to one already seen are
    #   ignored. Only works in channels with history enabled.
    # @param version_epoch [String, nil] The epoch of version. When it changes, Centrifugo
    #   accepts the publication even if its version is lower than before.
    # @return [Pending<PublishResult>]
    def publish(
      channel:,
      data: nil,
      b64data: nil,
      skip_history: nil,
      tags: nil,
      idempotency_key: nil,
      delta: nil,
      version: nil,
      version_epoch: nil
    )
      add("publish", PublishResult) do
        Requests.publish(
          channel,
          data,
          b64data,
          skip_history,
          tags,
          idempotency_key,
          delta,
          version,
          version_epoch
        )
      end
    end

    # Publishes the same data into many channels.
    #
    # Adds the command to the batch: its Pending holds the result once the batch
    # is sent, and raises BroadcastFailedChannelsError when any channel failed.
    #
    # @param channels [Array<String>] The list of channels to publish into. Required.
    # @param data [Object, nil] The payload to publish into each channel. Required unless
    #   b64data is set. In the HTTP API it is any JSON value; over GRPC it may
    #   be binary.
    # @param b64data [String, nil] A base64-encoded binary payload, an alternative to `data` to
    #   send binary over the HTTP API. Centrifugo decodes it before publishing.
    # @param skip_history [Boolean, nil] Skips adding the publications to the channels' history.
    # @param tags [Hash{String => String}] A map of arbitrary string keys and values attached to each
    #   publication and delivered to clients.
    # @param idempotency_key [String, nil] Drops duplicate publications upon retries. It acts per
    #   channel: a broadcast retried with the same key is not published again
    #   into the channels which already have it. Results are kept for 5 minutes
    #   by default. The memory, Redis and PostgreSQL brokers keep keys; the
    #   NATS broker ignores them.
    # @param delta [Boolean, nil] Tells Centrifugo to construct a delta update, if possible, when
    #   broadcasting the publications to subscribers.
    # @param version [Integer, nil] When > 0, the version of the document being sent:
    #   publications with a version less than or equal to one already seen are
    #   ignored. Only works in channels with history enabled.
    # @param version_epoch [String, nil] The epoch of version. When it changes, Centrifugo
    #   accepts the publication even if its version is lower than before.
    # @return [Pending<BroadcastResult>]
    def broadcast(
      channels:,
      data: nil,
      b64data: nil,
      skip_history: nil,
      tags: nil,
      idempotency_key: nil,
      delta: nil,
      version: nil,
      version_epoch: nil
    )
      add_broadcast do
        Requests.broadcast(
          channels,
          data,
          b64data,
          skip_history,
          tags,
          idempotency_key,
          delta,
          version,
          version_epoch
        )
      end
    end

    # Subscribes active sessions of a user to a channel
    # (server-side subscription). It does not create a streaming subscription
    # for the caller.
    #
    # Adds the command to the batch: its Pending holds the result once the batch
    # is sent.
    #
    # @param channel [String, nil] The name of the channel to subscribe to. Required.
    # @param user [String, nil] The ID of the user to subscribe. Required, unless all_users is
    #   used in Centrifugo PRO.
    # @param expire_at [Integer, nil] The Unix time in seconds when the subscription expires.
    # @param info [Object, nil] Custom channel info attached to the subscription, used in
    #   presence and join/leave messages.
    # @param b64info [String, nil] Info as base64, for binary. Centrifugo decodes it.
    # @param client [String, nil] Limits the call to the connection with this client ID. user is
    #   still required.
    # @param data [Object, nil] Custom subscription data sent to the client in the Subscribe
    #   push.
    # @param b64data [String, nil] Data as base64, for binary. Centrifugo decodes it.
    # @param recover_since [StreamPosition, Hash, nil] The stream position to recover publications from.
    # @param override [SubscribeOptionOverride, Hash, nil] Dynamically overrides some channel options set in the
    #   Centrifugo configuration.
    # @param session [String, nil] Limits the call to the connection with this session ID. user
    #   is still required.
    # @param label_filter [FilterNode, Hash, nil] Restricts the call to clients whose labels match this
    #   filter. Centrifugo PRO only.
    # @param all_users [Boolean, nil] When user is empty, targets every connection on every node
    #   instead of the anonymous-only bucket. No effect when user is non-empty.
    #   Without label_filter it acts on every connection. Centrifugo PRO only.
    # @return [Pending<SubscribeResult>]
    def subscribe(
      channel:,
      user: nil,
      expire_at: nil,
      info: nil,
      b64info: nil,
      client: nil,
      data: nil,
      b64data: nil,
      recover_since: nil,
      override: nil,
      session: nil,
      label_filter: nil,
      all_users: nil
    )
      add("subscribe", SubscribeResult) do
        Requests.subscribe(
          channel,
          user,
          expire_at,
          info,
          b64info,
          client,
          data,
          b64data,
          recover_since,
          override,
          session,
          label_filter,
          all_users
        )
      end
    end

    # Unsubscribes a user from a channel.
    #
    # Adds the command to the batch: its Pending holds the result once the batch
    # is sent.
    #
    # @param channel [String, nil] The name of the channel to unsubscribe from. Required.
