  # The commands of Command, one per method of api.proto.
  #
  # @api private
  module CommandMethods
    # Publishes data into a channel.
    #
    # The command making the call, checked as a Client checks it.
    #
    # @param channel [String, nil] The name of the channel to publish into. Required.
    # @param data [Object, nil] The payload to publish. Required unless b64data is set. In the
    #   HTTP API it is any JSON value; over GRPC it may be binary.
