      data: nil,
      b64data: nil,
      stream_data: nil,
      b64stream_data: nil,
      tags: nil,
      idempotency_key: nil,
      delta: nil,
      version: nil,
      version_epoch: nil,
      score: nil,
      key_mode: nil
    )
      build("map_publish") do
        Requests.map_publish(
          channel,
          key,
          data,
          b64data,
          stream_data,
          b64stream_data,
          tags,
          idempotency_key,
          delta,
          version,
          version_epoch,
          score,
          key_mode
        )
      end
    end

